def monitor_cpu():
    """
    监控 CPU 使用率，获取前 5 高的进程，每秒记录一次日志。
    日志存放在当天目录下的 cpu.log 中。
    """
    while not stop_event.is_set():
        try:
            # 构造 ps 命令，获取 CPU 占用率前 5 的进程
            cmd = "ps -eo comm,pcpu --no-headers --sort=-pcpu | head -n 5"
            output = subprocess.check_output(cmd, shell=True, universal_newlines=True)
        except subprocess.CalledProcessError as e:
            print(f"Error executing ps command: {e}")
            time.sleep(1)
            continue

        process_list = []
        for line in output.strip().split('\n'):
            if line:
                # 使用正则表达式或更安全的分割方式处理进程名可能包含空格的情况
                parts = line.strip().rsplit(None, 1)  # 从右边分割，确保CPU使用率是最后一个字段
                if len(parts) == 2:
                    name, cpu_usage = parts
                    try:
                        cpu_usage = float(cpu_usage)
                    except ValueError:
                        continue
                    process_list.append((name, cpu_usage))

        timestamp = datetime.now().strftime("[%Y-%m-%d %H:%M:%S]")
        log_line = f"{timestamp} CPU[%]:"
        for name, cpu_usage in process_list:
            log_line += f"{name}:{cpu_usage:.2f}; "
        log_line += "\n"

        # 每次写入时获取当天的日志文件路径
        cpu_log_file = get_log_file_path("cpu.log")
        with open(cpu_log_file, "a") as log_file:
            log_file.write(log_line)

        time.sleep(1)

