# -*- coding: utf-8 -*-
import json
import os
import queue
import threading
import time
from typing import Any, Callable, Dict, List, Optional, Tuple
import requests
from log import logger
from sys_prompt.nav_agent import NavAgent
from sys_prompt.box_agent import BoxAgent
from sys_prompt.function_prompt import available_functions


CMD_ACTION = "answer"
STATE_TEXT_GENERATE = "text_generate"
STATE_FUNCTION_CALL = "function_call"
STATE_FINISH = "finish"

INTENTION_NO = "<|intention_no|>"
INTENTION_YES = "<|intention_yes|>"
INTENTION_SILENCE = "<|silence|>"
INTENTION_NO_SPEAKING = "<|speaking|>"
SPECIAL_TOKENS = [INTENTION_NO, INTENTION_YES, INTENTION_SILENCE, INTENTION_NO_SPEAKING]
IGNORE_SPECIAL_TOKENS = [INTENTION_NO, INTENTION_SILENCE, INTENTION_NO_SPEAKING]




class OpenaiSdkThread(threading.Thread):
    """
    双线程版本：
    1) detector 线程：按原始队列顺序做意图分类（第一次 API）
    2) responder 线程：消费预处理消息；YES 再二次请求完整回答（第二次 API）

    仅 YES 场景触发二次请求；非 YES 只入历史，不回答。
    """

    INTENTION_HTTP_TIMEOUT = (3, 15)
    STREAM_HTTP_TIMEOUT = (5, 120)
    MAX_TOOL_CALL_ROUNDS = 3

    def __init__(
        self,
        in_queue: "queue.Queue[Dict[str, Any]]",
        on_message: Callable[[str], None],
        *,
        model: str = "qwen25_omni",
        base_url: Optional[str] = "http://192.168.31.59:8000/v1",
        responder_base_url: Optional[str] = "http://192.168.31.59:8001/v1",
        api_key: <云凭据_01> = "none",
        agent_id: str = "main",
        lang: str = "cn",
        history_rounds: int = 12,
        robot_name: str = "g1_pub",
    ) -> None:
        super().__init__()
        self.daemon = True
        self.is_running = True
        self.in_queue = in_queue
        self.on_message = on_message
        self.model = model
        self.base_url = base_url or os.environ.get("OPENAI_BASE_URL", "http://127.0.0.1:8000/v1") # 意图检测
        self.responder_base_url = responder_base_url or os.environ.get("OPENAI_BASE_URL", "http://127.0.0.1:8001/v1") # 回答

        self.api_key = <云凭据_01> or os.environ.get("OPENCLAW_GATEWAY_TOKEN") or os.environ.get("OPENAI_API_KEY") or "dummy"
        self.agent_id = agent_id
        self.lang = lang
        self.history_rounds = max(1, int(history_rounds))
        self.intention_history_rounds = self.history_rounds

        self._processed_queue: "queue.Queue[Dict[str, Any]]" = queue.Queue()
        self._detector_history_by_session: Dict[str, List[Dict[str, Any]]] = {}
        self._responder_history_by_session: Dict[str, List[Dict[str, Any]]] = {}
        self._history_lock = threading.RLock()

        self._detector_thread: Optional[threading.Thread] = None
        self._responder_thread: Optional[threading.Thread] = None

        # 每来一个 YES 递增，responder 流式中若检测到版本增长则立即中断当前回答
        self._interrupt_lock = threading.Lock()
        self._interrupt_version = 0

        self.detector_session = requests.Session()
        self.responder_session = requests.Session()

        self.sys_prompt_agents = {
            "g1_pub": NavAgent(),
            "g1_box": BoxAgent(),
        }
        self.sys_prompt_agent: NavAgent = self.sys_prompt_agents.get(robot_name, NavAgent())
        self.tool_schemas = self._build_tool_schemas()

    def build_system_prompt(self, data: dict = None, use_intention:bool = False) -> str:

        return self.sys_prompt_agent.get_system_prompt(data=data, use_intention=use_intention)

    def stop(self) -> None:
        self.is_running = False
        self.in_queue.put(None)
        self._processed_queue.put(None)
        if self._detector_thread and self._detector_thread.is_alive():
            self._detector_thread.join(timeout=1.0)
        if self._responder_thread and self._responder_thread.is_alive():
            self._responder_thread.join(timeout=1.0)
        self.detector_session.close()
        self.responder_session.close()

    def _next_interrupt_version(self) -> int:
        with self._interrupt_lock:
            self._interrupt_version += 1
            return self._interrupt_version

    def _get_interrupt_version(self) -> int:
        with self._interrupt_lock:
            return self._interrupt_version

    def _emit(self, uid: str, text: str, state: str, action: str = "") -> None:
        if text:
            for token in SPECIAL_TOKENS:
                text = text.replace(token, "")
        if action:
            for token in SPECIAL_TOKENS:
                action = action.replace(token, "")
        if state != STATE_FINISH and not text and not action:
            return
        msg = {
            "cmd": CMD_ACTION,
            "data": {
                "uid": uid,
                "text": text,
                "action": action,
                "lang": self.lang,
                "state": state,
            },
        }
        self.on_message(json.dumps(msg, ensure_ascii=False))

    @staticmethod
    def _extract_text_from_content_obj(content_obj: Any) -> str:
        if isinstance(content_obj, str):
            return content_obj
        if isinstance(content_obj, list):
            tmp = []
            for item in content_obj:
                if isinstance(item, dict):
                    if "text" in item:
                        tmp.append(str(item["text"]))
                    elif item.get("type") == "text" and "text" in item:
                        tmp.append(str(item["text"]))
                    elif "content" in item:
                        tmp.append(str(item["content"]))
                else:
                    tmp.append(str(item))
            return "".join(tmp)
        return str(content_obj or "")

    @staticmethod
    def _chat_completions_url(base_url: str) -> str:
        return base_url.rstrip("/") + "/chat/completions"

    def _build_json_headers(self) -> Dict[str, str]:
        return {
            "Content-Type": "application/json",
            "Authorization": <访问令牌_01>"Bearer {self.api_key}",
            "x-openclaw-agent-id": self.agent_id,
        }

    def _build_sse_headers(self) -> Dict[str, str]:
        headers = self._build_json_headers()
        headers["Accept"] = "text/event-stream"
        return headers

    @staticmethod
    def _build_tool_schemas() -> List[Dict[str, Any]]:
        schemas: List[Dict[str, Any]] = []
        for name, fn in available_functions.items():
            if not callable(fn):
                continue
            schemas.append(
                {
                    "type": "function",
                    "function": {
                        "name": name,
                        "description": (fn.__doc__ or "").strip() or f"Call function {name}",
                        "parameters": {
                            "type": "object",
                            "properties": {},
                            "additionalProperties": True,
                        },
                    },
                }
            )
        return schemas

    def _post_chat_completions(
        self,
        session: requests.Session,
        base_url: str,
        messages: List[Dict[str, Any]],
        *,
        stream: bool,
        temperature: Optional[float] = None,
        max_tokens: Optional[int] = None,
        extra_body: Optional[Dict[str, Any]] = None,
        timeout: Optional[Tuple[int, int]] = None,
        include_tools: bool = False,
    ) -> requests.Response:
        payload: Dict[str, Any] = {
            "model": self.model,
            "messages": messages,
            "stream": stream,
        }
        if include_tools and self.tool_schemas:
            payload["tools"] = self.tool_schemas
            payload["tool_choice"] = "auto"
        if temperature is not None:
            payload["temperature"] = temperature
        if max_tokens is not None:
            payload["max_tokens"] = max_tokens
        if extra_body:
            payload.update(extra_body)

        response = session.post(
            self._chat_completions_url(base_url),
            headers=self._build_sse_headers() if stream else self._build_json_headers(),
            json=payload,
            stream=stream,
            timeout=timeout or (self.STREAM_HTTP_TIMEOUT if stream else self.INTENTION_HTTP_TIMEOUT),
        )
        response.raise_for_status()
        return response

    @staticmethod
    def _to_str_content(value: Any) -> str:
        if isinstance(value, str):
            return value
        try:
            return json.dumps(value, ensure_ascii=False)
        except Exception:
            return str(value)

    def _execute_tool_calls(self, tool_calls: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
        tool_messages: List[Dict[str, Any]] = []
        for idx, tc in enumerate(tool_calls):
            fn = tc.get("function") or {}
            name = str(fn.get("name") or "")
            raw_args = str(fn.get("arguments") or "")
            tool_call_id = str(tc.get("id") or f"tool_{idx}_{int(time.time() * 1000)}")

            if not name:
                result = {"error": "tool name missing"}
                tool_messages.append(
                    {"role": "tool", "tool_call_id": tool_call_id, "content": self._to_str_content(result)}
                )
                continue

            try:
                args = json.loads(raw_args) if raw_args else {}
            except Exception:
                args = {"raw_arguments": raw_args}

            fn_impl = available_functions.get(name)
            if not callable(fn_impl):
                result = {"error": f"tool '{name}' not found"}
            else:
                try:
                    if isinstance(args, dict):
                        result = fn_impl(args)
                    else:
                        result = fn_impl({"input": args})
                except Exception as exc:
                    result = {"error": f"tool '{name}' execution failed: {exc}"}

            tool_messages.append(
                {
                    "role": "tool",
                    "tool_call_id": tool_call_id,
                    "content": self._to_str_content(result),
                }
            )
        return tool_messages

    def _chat_completion_once(
        self,
        session: requests.Session,
        base_url: str,
        messages: List[Dict[str, Any]],
        *,
        temperature: Optional[float] = None,
        max_tokens: Optional[int] = None,
        extra_body: Optional[Dict[str, Any]] = None,
    ) -> str:
        response = self._post_chat_completions(
            session,
            base_url,
            messages,
            stream=False,
            temperature=temperature,
            max_tokens=max_tokens,
            extra_body=extra_body,
            timeout=self.INTENTION_HTTP_TIMEOUT,
            include_tools=True,
        )
        try:
            data = response.json()
        finally:
            response.close()
        choices = data.get("choices") or []
        if not choices:
            return ""
        message = choices[0].get("message") or {}
        return self._extract_text_from_content_obj(message.get("content"))

    def _iter_sse_events(self, response: requests.Response):
        for raw_line in response.iter_lines(chunk_size=1, decode_unicode=True):
            if not raw_line:
                continue
            line = raw_line.strip()
            if line.startswith(":"):
                continue
            if not line.startswith("data:"):
                continue
            data_str = line[5:].strip()
            if not data_str:
                continue
            if data_str == "[DONE]":
                break
            try:
                event = json.loads(data_str)
            except json.JSONDecodeError:
                logger.warning(f"invalid sse json: {data_str[:200]}")
                continue
            choices = event.get("choices") or []
            if not choices:
                continue
            choice0 = choices[0] or {}
            delta = choice0.get("delta") or {}
            yield {
                "content": self._extract_text_from_content_obj(delta.get("content")),
                "tool_calls": delta.get("tool_calls"),
                "function_call": delta.get("function_call"),
                "finish_reason": choice0.get("finish_reason"),
            }

    @staticmethod
    def _extract_payload(item: Dict[str, Any]) -> Dict[str, Any]:
        if "data" in item and isinstance(item["data"], dict):
            return item["data"]
        return item

    @staticmethod
    def _build_user_content(payload: Dict[str, Any]) -> List[Dict[str, Any]]:
        parts: List[Dict[str, Any]] = []
        q = payload.get("question")
        v = payload.get("vision")
        s = payload.get("speech")
        audio_format = payload.get("speech_format") or payload.get("audio_format") or payload.get("format") or "mp3"

        if q is not None:
            parts.append({"type": "text", "text": str(q)})
        if v is not None:
            if isinstance(v, str):
                if v.startswith("http://") or v.startswith("https://") or v.startswith("data:image"):
                    image_url = v
                else:
                    image_url = f"data:image/jpeg;base64,{v}"
            else:
                image_url = str(v)
            parts.append({"type": "image_url", "image_url": {"url": image_url}})
        if s is not None:
            parts.append(
                {
                    "type": "input_audio",
                    "input_audio": {"data": str(s), "format": str(audio_format)},
                }
            )
        return parts

    @staticmethod
    def _sanitize_text(txt: str) -> str:
        for token in IGNORE_SPECIAL_TOKENS:
            txt = txt.replace(token, "")
        return txt.replace(INTENTION_YES, "")

    def _history_key(self, payload: Dict[str, Any]) -> str:
        return str(
            payload.get("session_id")
            or payload.get("session")
            or payload.get("user_id")
            or payload.get("sn")
            or self.agent_id
        )

    @staticmethod
    def _trim_history(history: List[Dict[str, Any]], rounds: int) -> List[Dict[str, Any]]:
        max_items = max(1, rounds) * 2
        if len(history) <= max_items:
            return history
        return history[-max_items:]

    def _get_detector_history(self, key: str) -> List[Dict[str, Any]]:
        with self._history_lock:
            if key not in self._detector_history_by_session:
                self._detector_history_by_session[key] = []
            self._detector_history_by_session[key] = self._trim_history(
                self._detector_history_by_session[key], self.intention_history_rounds
            )
            return self._detector_history_by_session[key]

    def _get_responder_history(self, key: str) -> List[Dict[str, Any]]:
        with self._history_lock:
            if key not in self._responder_history_by_session:
                self._responder_history_by_session[key] = []
            self._responder_history_by_session[key] = self._trim_history(
                self._responder_history_by_session[key], self.history_rounds
            )
            return self._responder_history_by_session[key]

    def _append_detector_history(self, key: str, user_content: List[Dict[str, Any]], token: <访问令牌_01> -> None:
        h = self._get_detector_history(key)
        h.append({"role": "user", "content": user_content})
        h.append({"role": "assistant", "content": token})

    def _append_responder_history_user_only(self, key: str, user_content: List[Dict[str, Any]]) -> None:
        h = self._get_responder_history(key)
        h.append({"role": "user", "content": user_content})

    def _append_responder_history_round(self, key: str, user_content: List[Dict[str, Any]], answer: str) -> None:
        h = self._get_responder_history(key)
        h.append({"role": "user", "content": user_content})
        h.append({"role": "assistant", "content": answer})

    def _build_messages(self, key: str, user_content: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
        history = list(self._get_responder_history(key))
        messages = self.build_system_prompt(user_content, use_intention=True)
        messages.extend(history)
        messages.append({"role": "user", "content": user_content})
        return messages

    @staticmethod
    def _extract_raw_intention_token(raw: str) -> str:
        """Return the raw special token from the model output for history storage."""
        if not raw:
            return INTENTION_SILENCE
        if INTENTION_YES in raw:
            return INTENTION_YES
        if INTENTION_NO in raw:
            return INTENTION_NO
        if INTENTION_SILENCE in raw:
            return INTENTION_SILENCE
        if INTENTION_NO_SPEAKING in raw:
            return INTENTION_NO_SPEAKING
        return INTENTION_NO

    @staticmethod
    def _normalize_detector_token(token: <访问令牌_01> -> str:
        if token =<访问令牌_01> INTENTION_YES:
            return INTENTION_YES
        if token =<访问令牌_01> INTENTION_SILENCE:
            return INTENTION_SILENCE
        return INTENTION_NO_SPEAKING

    def _classify_intention(self, session_key: str, content: List[Dict[str, Any]]) -> str:
        if not content:
            return "no"
        # 意图判断只取最近 N 轮，减少 prefill token 数，提升 APC 命中率
        recent = list(self._get_detector_history(session_key))
        intent_messages = self.build_system_prompt(data=content, use_intention=True)
        intent_messages.extend(recent)
        intent_messages.append({"role": "user", "content": content})

        text = self._chat_completion_once(
            self.detector_session,
            self.base_url,
            intent_messages,
            temperature=0.5,
            max_tokens=4,
            extra_body={"skip_special_tokens": False},
        )
        return self._extract_raw_intention_token(text)

    def _detector_loop(self) -> None:
        seq = 0
        while self.is_running:
            try:
                item = self.in_queue.get(timeout=0.1)
            except queue.Empty:
                continue
            if item is None:
                continue
            try:
                payload = self._extract_payload(item)
                uid = str(payload.get("uid") or payload.get("id") or f"unknown-{seq}")
                captured_at: float = payload.get("captured_at") or time.time()
                t0 = time.time()
                logger.debug(
                    f"[timing][{uid}] detector received: "
                    f"+{(t0 - captured_at) * 1000:.0f}ms since capture"
                )
                session_key = self._history_key(payload)
                content = self._build_user_content(payload)
                intention_token = self._classify_intention(session_key, content)
                detector_token = self._normalize_detector_token(intention_token)
                self._append_detector_history(session_key, content, detector_token)
                t1 = time.time()
                logger.debug(
                    f"[timing][{uid}] intention={intention_token}, detector_token={detector_token}: "
                    f"+{(t1 - captured_at) * 1000:.0f}ms since capture "
                    f"(classify took {(t1 - t0) * 1000:.0f}ms)"
                )
                if intention_token == INTENTION_YES:
                    self._next_interrupt_version()
                    # content.append({"type": "text", "text": INTENTION_YES})

                self._processed_queue.put(
                    {
                        "seq": seq,
                        "uid": uid,
                        "session_key": session_key,
                        "content": content,
                        "intention_token": intention_token,
                        "captured_at": captured_at,
                    }
                )
                seq += 1

                # if intention_token == INTENTION_YES:
                #     time.sleep(2)
            except Exception as exc:
                logger.error(f"detector loop error: {exc}")

    @staticmethod
    def _split_at_partial_tag(buf: str, tag: str) -> Tuple[str, str]:
        """
        将 buf 分成 (可安全输出部分, 需要保留部分)。
        保留部分是 buf 末尾与 tag 某个前缀完全匹配的最长后缀，
        避免跨 chunk 的 tag 被截断后误输出。
        例如: buf="hello\n```", tag="```python" → ("hello\n", "```")
        """
        for length in range(min(len(tag) - 1, len(buf)), 0, -1):
            if buf.endswith(tag[:length]):
                return buf[:-length], buf[-length:]
        return buf, ""

    def _stream_answer(
        self,
        uid: str,
        session_key: str,
        content: List[Dict[str, Any]],
        start_version: int,
        captured_at: float = 0.0,
    ) -> str:
        messages = self._build_messages(session_key, content)
        open_tag = "```python"
        close_tag = "```"
        text_buf = ""
        code_buf = ""
        in_code = False
        answer_parts: List[str] = []
        first_token = True

        for _ in range(self.MAX_TOOL_CALL_ROUNDS + 1):
            tool_call_buf: Dict[int, Dict[str, Any]] = {}
            finish_reason: Optional[str] = None
            stream = self._post_chat_completions(
                self.responder_session,
                self.responder_base_url,
                messages=messages,
                stream=True,
                temperature=0.5,
                timeout=self.STREAM_HTTP_TIMEOUT,
                include_tools=True,
            )
            try:
                for event in self._iter_sse_events(stream):
                    if self._get_interrupt_version() > start_version:
                        self._emit(uid, "", STATE_FINISH)
                        return "".join(answer_parts)
                    tool_calls_delta = event.get("tool_calls") or []
                    if isinstance(tool_calls_delta, list):
                        for tc in tool_calls_delta:
                            if not isinstance(tc, dict):
                                continue
                            idx = int(tc.get("index", 0))
                            buf = tool_call_buf.setdefault(
                                idx,
                                {
                                    "id": tc.get("id", ""),
                                    "type": tc.get("type", "function"),
                                    "function": {"name": "", "arguments": ""},
                                },
                            )
                            if tc.get("id"):
                                buf["id"] = tc.get("id")
                            if tc.get("type"):
                                buf["type"] = tc.get("type")
                            fn_delta = tc.get("function") or {}
                            if isinstance(fn_delta, dict):
                                if fn_delta.get("name"):
                                    buf["function"]["name"] += str(fn_delta.get("name"))
                                if fn_delta.get("arguments"):
                                    buf["function"]["arguments"] += str(fn_delta.get("arguments"))

                    legacy_fc = event.get("function_call")
                    if isinstance(legacy_fc, dict):
                        buf = tool_call_buf.setdefault(
                            0,
                            {
                                "id": f"legacy_{int(time.time() * 1000)}",
                                "type": "function",
                                "function": {"name": "", "arguments": ""},
                            },
                        )
                        if legacy_fc.get("name"):
                            buf["function"]["name"] += str(legacy_fc.get("name"))
                        if legacy_fc.get("arguments"):
                            buf["function"]["arguments"] += str(legacy_fc.get("arguments"))

                    finish_reason = event.get("finish_reason") or finish_reason
                    if finish_reason in ("tool_calls", "function_call"):
                        continue

                    piece = event.get("content") or ""
                    piece = self._sanitize_text(piece)
                    if not piece:
                        continue
                    if first_token:
                        t_first = time.time()
                        ref = captured_at or t_first
                        logger.debug(
                            f"[timing][{uid}] first token: <访问令牌_01> - ref) * 1000:.0f}ms since capture"
                        )
                        first_token = False
                    text_buf += piece
                    while True:
                        if not in_code:
                            p = text_buf.find(open_tag)
                            if p >= 0:
                                before = text_buf[:p]
                                if before:
                                    self._emit(uid, before, STATE_TEXT_GENERATE)
                                    answer_parts.append(before)
                                text_buf = text_buf[p + len(open_tag):]
                                in_code = True
                            else:
                                safe, text_buf = self._split_at_partial_tag(text_buf, open_tag)
                                if safe:
                                    self._emit(uid, safe, STATE_TEXT_GENERATE)
                                    answer_parts.append(safe)
                                break
                        else:
                            e = text_buf.find(close_tag)
                            if e >= 0:
                                code_buf += text_buf[:e]
                                if code_buf.strip():
                                    self._emit(uid, "", STATE_FUNCTION_CALL, action=code_buf)
                                    answer_parts.append(f"```python\n{code_buf}\n```")
                                code_buf = ""
                                text_buf = text_buf[e + len(close_tag):]
                                in_code = False
                            else:
                                safe, text_buf = self._split_at_partial_tag(text_buf, close_tag)
                                code_buf += safe
                                break
            except Exception as exc:
                logger.warning(f"stream answer interrupted uid={uid}: {exc}")
            finally:
                close_fn = getattr(stream, "close", None)
                if callable(close_fn):
                    try:
                        close_fn()
                    except Exception:
                        pass

            if not tool_call_buf:
                break

            tool_calls = []
            for idx in sorted(tool_call_buf.keys()):
                tc = tool_call_buf[idx]
                fn = tc.get("function") or {}
                tool_calls.append(
                    {
                        "id": tc.get("id") or f"tool_{idx}_{int(time.time() * 1000)}",
                        "type": tc.get("type") or "function",
                        "function": {
                            "name": fn.get("name", ""),
                            "arguments": fn.get("arguments", ""),
                        },
                    }
                )

            messages.append({"role": "assistant", "content": "", "tool_calls": tool_calls})
            messages.extend(self._execute_tool_calls(tool_calls))
        # 流结束后刷出剩余缓冲
        if in_code:
            # 未闭合的代码块：text_buf 可能含部分闭标签，一并纳入
            remaining = code_buf + text_buf
            if remaining.strip():
                self._emit(uid, "", STATE_FUNCTION_CALL, action=remaining)
                answer_parts.append(f"```python\n{remaining}\n```")
        else:
            remaining = text_buf
            if remaining:
                self._emit(uid, remaining, STATE_TEXT_GENERATE)
                answer_parts.append(remaining)

        self._emit(uid, "", STATE_FINISH)
        return "".join(answer_parts)

    def _responder_loop(self) -> None:
        while self.is_running:
            try:
                task = self._processed_queue.get(timeout=10)
            except queue.Empty:
                continue
            if task is None:
                continue
            try:
                uid = task["uid"]
                session_key = task["session_key"]
                content = task["content"]
                intention_token = task["intention_token"]
                captured_at: float = task.get("captured_at") or time.time()
                logger.debug(
                    f"[timing][{uid}] responder received (intention={intention_token}): "
                    f"+{(time.time() - captured_at) * 1000:.0f}ms since capture"
                )
                if not content:
                    self._emit(uid, "", STATE_FINISH)
                    continue
                if intention_token != INTENTION_YES:
                    # responder 历史只维护已消化的片段；silence/speaking/no 直接作为 assistant token 入历史
                    self._append_responder_history_round(session_key, content, intention_token)
                    continue
                start_version = self._get_interrupt_version()
                answer = self._stream_answer(uid, session_key, content, start_version, captured_at)
                if answer.strip():
                    # yes 场景：训练数据格式为 <|intention_yes|> + 实际回答内容
                    self._append_responder_history_round(session_key, content, INTENTION_YES + answer)
            except Exception as exc:
                logger.error(f"responder loop error: {exc}")
                try:
                    uid = task.get("uid", "unknown")
                    self._emit(uid, f"OpenAI SDK error: {exc}", STATE_TEXT_GENERATE)
                    self._emit(uid, "", STATE_FINISH)
                except Exception:
                    logger.error("responder emit failed")

    def run(self) -> None:
        logger.info("openai sdk thread started (two-thread mode)")
        self._detector_thread = threading.Thread(target=self._detector_loop, daemon=True)
        self._responder_thread = threading.Thread(target=self._responder_loop, daemon=True)
        self._detector_thread.start()
        self._responder_thread.start()
        while self.is_running:
            time.sleep(0.05)

