import base64
import io
import json
import math
import pathlib
import tarfile
import threading
from concurrent.futures import ThreadPoolExecutor

import yaml
from unitree_dds_wrapper.idl import std_msgs
from unitree_dds_wrapper.publisher import Publisher
from unitree_dds_wrapper.subscription import RequestSubscription

from r1_arm_action import ArmStatusCode, logger

API_ID_UPLOAD_HANDSHAKE = 1001
API_ID_DOWNLOAD_HANDSHAKE = 1002
API_ID_DOWNLOAD_SLICE = 1003

INBOUND_TOPIC = "rt/arm_service_inbound"
OUTBOUND_TOPIC = "rt/arm_service_outbound"
SLICE_BYTES = 48 * 1024


class FileSyncError(ValueError):
    pass


def validate_files(files):
    if not isinstance(files, list) or not files:
        raise FileSyncError("files must be a non-empty list")

    seen = set()
    for name in files:
        if not isinstance(name, str) or not name:
            raise FileSyncError("file name must be a non-empty string")

        path = pathlib.PurePosixPath(name)
        if (
            path.is_absolute()
            or len(path.parts) != 1
            or "\\" in name
            or name in (".", "..")
            or ".." in path.parts
            or pathlib.Path(name).suffix != ".yaml"
        ):
            raise FileSyncError(f"invalid yaml file name: {name}")

        if name in seen:
            raise FileSyncError(f"duplicate yaml file name: {name}")
        seen.add(name)

    return files


def make_archive(source_dir, files):
    source_dir = pathlib.Path(source_dir)
    files = validate_files(files)

    buffer = io.BytesIO()
    with tarfile.open(fileobj=buffer, mode="w:gz") as tar:
        for name in files:
            file_path = source_dir / name
            if not file_path.is_file():
                raise FileSyncError(f"yaml file does not exist: {name}")
            tar.add(file_path, arcname=name)
    return buffer.getvalue()


def split_archive(archive, slice_bytes=SLICE_BYTES):
    if slice_bytes <= 0:
        raise ValueError("slice_bytes must be positive")

    total = max(1, math.ceil(len(archive) / slice_bytes))
    return [
        {
            "slice_idx": idx,
            "total_slice_idx": total,
            "slice_content": base64.b64encode(
                archive[idx * slice_bytes : (idx + 1) * slice_bytes]
            ).decode("ascii"),
        }
        for idx in range(total)
    ]


def assemble_slices(slices):
    if not slices:
        raise FileSyncError("empty slices")

    total = slices[0].get("total_slice_idx")
    if not isinstance(total, int) or total <= 0 or len(slices) != total:
        raise FileSyncError("invalid total slice count")

    content = bytearray()
    for idx, item in enumerate(slices):
        if item.get("slice_idx") != idx or item.get("total_slice_idx") != total:
            raise FileSyncError("invalid slice index")
        try:
            content.extend(base64.b64decode(item["slice_content"], validate=True))
        except Exception as exc:
            raise FileSyncError("invalid slice content") from exc
    return bytes(content)


def extract_archive(archive, target_dir, files):
    target_dir = pathlib.Path(target_dir)
    files = set(validate_files(files))
    parsed_files = {}

    with tarfile.open(fileobj=io.BytesIO(archive), mode="r:gz") as tar:
        members = tar.getmembers()
        names = [member.name for member in members]
        if set(names) != files:
            raise FileSyncError("archive files do not match handshake files")

        for member in members:
            validate_files([member.name])
            if not member.isfile():
                raise FileSyncError(f"archive member is not a file: {member.name}")

            src = tar.extractfile(member)
            if src is None:
                raise FileSyncError(f"cannot read archive member: {member.name}")

            data = src.read()
            try:
                yaml.safe_load(data.decode("utf-8"))
            except Exception as exc:
                raise FileSyncError(f"invalid yaml file: {member.name}") from exc
            parsed_files[member.name] = data

    target_dir.mkdir(parents=True, exist_ok=True)
    for name, data in parsed_files.items():
        (target_dir / name).write_bytes(data)


class StringPublisher(Publisher):
    def __init__(self, topic):
        super().__init__(message=std_msgs.msg.dds_.String_, topic=topic)
        self.msg: std_msgs.msg.dds_.String_

    def publish_json(self, payload):
        msg = std_msgs.msg.dds_.String_()
        msg.data = json.dumps(payload)
        self.write(msg)


class DownloadSession:
    def __init__(self, files):
        self.files = files
        self.slices = {}
        self.total = None

    def add_slice(self, sliced_log):
        idx = sliced_log.get("slice_idx")
        total = sliced_log.get("total_slice_idx")
        if not isinstance(idx, int) or not isinstance(total, int):
            raise FileSyncError("invalid slice metadata")
        if idx < 0 or total <= 0 or idx >= total:
            raise FileSyncError("invalid slice index")
        if self.total is not None and total != self.total:
            raise FileSyncError("slice total changed")
        self.total = total
        self.slices[idx] = sliced_log
        return len(self.slices) == self.total

    def archive(self):
        return assemble_slices([self.slices[idx] for idx in range(self.total)])


class ArmFileSyncService:
    def __init__(self, runner, running_event, source_dir=None):
        self.runner = runner
        self.running_event = running_event
        self.source_dir = pathlib.Path(source_dir or runner.static_config_dir)
        self._pub = StringPublisher(OUTBOUND_TOPIC)
        self._sub = RequestSubscription(
            message=std_msgs.msg.dds_.String_,
            topic=INBOUND_TOPIC,
            handler=self._on_message,
        )
        self._executor = ThreadPoolExecutor(max_workers=2)
        self._download_sessions = {}
        self._upload_acks = {}
        self._lock = threading.Lock()

    def _on_message(self, _):
        msg = self._sub.take_one()
        if msg is None:
            return
        self._executor.submit(self._handle_message, msg.data)

    def _handle_message(self, data):
        try:
            payload = json.loads(data)
        except Exception:
            logger.error("Invalid file sync json message.")
            return

        if payload.get("type") == "res":
            self._handle_ack(payload)
            return

        api_id = payload.get("api_id")
        if api_id == API_ID_UPLOAD_HANDSHAKE:
            self._handle_upload(payload)
        elif api_id == API_ID_DOWNLOAD_HANDSHAKE:
            self._handle_download_handshake(payload)
        elif api_id == API_ID_DOWNLOAD_SLICE:
            self._handle_download_slice(payload)

    def _handle_ack(self, payload):
        key = (payload.get("req_id"), payload.get("api_id"))
        with self._lock:
            ack = self._upload_acks.get(key)
        if ack is not None:
            ack["code"] = payload.get("code", ArmStatusCode.COMMON.value)
            ack["event"].set()

    def _handle_upload(self, payload):
        req_id = payload.get("req_id")
        try:
            files = validate_files(payload.get("files"))
            archive = make_archive(self.source_dir, files)
        except Exception as exc:
            logger.error(f"Prepare upload archive failed: {exc}")
            self._send_response(req_id, API_ID_UPLOAD_HANDSHAKE, ArmStatusCode.COMMON)
            return

        self._send_response(req_id, API_ID_UPLOAD_HANDSHAKE, ArmStatusCode.SUCCESS)

        key = (req_id, API_ID_UPLOAD_HANDSHAKE)
        for sliced_log in split_archive(archive):
            ack = {"event": threading.Event(), "code": None}
            with self._lock:
                self._upload_acks[key] = ack
            self._pub.publish_json(
                {
                    "type": "req",
                    "req_id": req_id,
                    "api_id": API_ID_UPLOAD_HANDSHAKE,
                    "sliced_log": sliced_log,
                }
            )
            if not ack["event"].wait(timeout=5.0) or ack["code"] != 0:
                logger.error("Upload slice was not acknowledged.")
                break

        with self._lock:
            self._upload_acks.pop(key, None)

    def _handle_download_handshake(self, payload):
        req_id = payload.get("req_id")
        try:
            files = validate_files(payload.get("files"))
        except Exception as exc:
            logger.error(f"Invalid download files: {exc}")
            self._send_response(req_id, API_ID_DOWNLOAD_HANDSHAKE, ArmStatusCode.COMMON)
            return

        if self.running_event.is_set() or self.runner.teaching:
            self._send_response(
                req_id, API_ID_DOWNLOAD_HANDSHAKE, ArmStatusCode.ARMSDK_OCCUPIED
            )
            return

        with self._lock:
            self._download_sessions[req_id] = DownloadSession(files)
        self._send_response(req_id, API_ID_DOWNLOAD_HANDSHAKE, ArmStatusCode.SUCCESS)

    def _handle_download_slice(self, payload):
        req_id = payload.get("req_id")
        with self._lock:
            session = self._download_sessions.get(req_id)

        if session is None:
            self._send_response(req_id, API_ID_DOWNLOAD_SLICE, ArmStatusCode.COMMON)
            return

        try:
            done = session.add_slice(payload.get("sliced_log", {}))
            if done:
                if self.running_event.is_set() or self.runner.teaching:
