    self.buffer_ = self.buffer_.replace(':', '：')

    pos_yes = self.buffer_.find(INTENTION_YES)
    pos_no = self.buffer_.find(INTENTION_NO)
    if pos_yes > -1 :
        self.buffer_ = self.buffer_[pos_yes + len(INTENTION_YES):]
        self.intention_state_ = IntentionState.yes
    elif pos_no > -1 :
        self.buffer_ = self.buffer_[pos_no + len(INTENTION_NO):]
